         border: 1px solid #e9ecef;\\n            border-radius: 3px;\\n            padding: 10px;\\n            margin-bottom: 10px;\\n        }\\n        .tenant-share-header {\\n            display: flex;\\n            justify-content: space-between;\\n            align-items: center;\\n            margin-bottom: 8px;\\n            padding-bottom: 5px;\\n            border-bottom: 1px solid #e9ecef;\\n        }\\n        .tenant-share-name {\\n            font-weight: 500;\\n            color: #495057;\\n            font-size: 12px;\\n        }\\n        .tenant-share-percentage {\\n            background-color: #fd7e14;\\n            color: white;\\n            padding: 2px 8px;\\n            border-radius: 12px;\\n            font-size: 11px;\\n            font-weight: 600;\\n        }\\n        .tenant-share-breakdown {\\n            display: grid;\\n            grid-template-columns: repeat(3, 1fr);\\n            gap: 15px;\\n            font-size: 12px;\\n        }\\n        .cost-item {\\n            display: flex;\\n            flex-direction: column;\\n            align-items: center;\\n            text-align: center;\\n        }\\n        .cost-label {\\n            color: #6c757d;\\n            font-size: 10px;\\n            text-transform: uppercase;\\n            letter-spacing: 0.5px;\\n            margin-bottom: 3px;\\n        }\\n        .cost-value {\\n            font-weight: 600;\\n            color: #495057;\\n        }\\n        .tenant-cost {\\n            color: #28a745;\\n        }\\n        .remaining-cost {\\n            color: #fd7e14;\\n        }\\n        .tenant-share-note {\\n            background-color: #fdf2e9;\\n            border: 1px solid #fd7e14;\\n            border-radius: 3px;\\n            padding: 8px;\\n            margin-top: 10px;\\n            font-size: 12px;\\n            color: #c1611d;\\n        }\\n        @media print {\\n            body { background-color: white; }\\n            .section { border: 1px solid #